#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0u, 0u, 0u, 0u};

    // Per-thread bins to avoid races; reduce at end.
    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 4>> local(static_cast<std::size_t>(max_threads), {0u, 0u, 0u, 0u});

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<std::size_t>(tid)];

        #pragma omp for schedule(static_cast<omp_sched_t>(omp_sched_static))
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Define quadrants including axes as in the example:
            // Q0: x>0, y>=0; Q1: x<=0, y>0; Q2: x<0, y<=0; Q3: x>=0, y<0
            if (x > 0.0 && y >= 0.0) {
                ++lb[0];
            } else if (x <= 0.0 && y > 0.0) {
                ++lb[1];
            } else if (x < 0.0 && y <= 0.0) {
                ++lb[2];
            } else if (x >= 0.0 && y < 0.0) {
                ++lb[3];
            }
        }
    }

    for (const auto &lb : local) {
        bins[0] += lb[0];
        bins[1] += lb[1];
        bins[2] += lb[2];
        bins[3] += lb[3];
    }
}
